def choose_move(observation):
    w = observation["grid_width"]; h = observation["grid_height"]
    sx, sy = observation["self_position"]
    ox, oy = observation["opponent_position"]
    obstacles = set((p[0], p[1]) for p in observation.get("obstacles", []))
    moves = [(-1, -1), (-1, 0), (-1, 1), (0, -1), (0, 0), (0, 1), (1, -1), (1, 0), (1, 1)]

    self_role = (observation.get("self_role", "") or "").lower()
    is_pursuer = ("pursuer" in self_role) or ("chaser" in self_role) or ("hunter" in self_role) or ("pursuit" in self_role)

    def valid(x, y):
        return 0 <= x < w and 0 <= y < h and (x, y) not in obstacles

    def step(x, y, dx, dy):
        nx, ny = x + dx, y + dy
        if not valid(nx, ny):
            return x, y
        return nx, ny

    def dist2(x1, y1, x2, y2):
        dx = x1 - x2; dy = y1 - y2
        return dx * dx + dy * dy

    def mobility(x, y):
        c = 0
        for dx, dy in moves:
            nx, ny = x + dx, y + dy
            if valid(nx, ny):
                c += 1
        return c

    # If already at opponent, any move ends capture check elsewhere; keep deterministic
    if sx == ox and sy == oy:
        return [0, 0]

    # Candidate moves for self
    candidates = []
    for dx, dy in moves:
        nx, ny = step(sx, sy, dx, dy)
        candidates.append((dx, dy, nx, ny))

    # If pursuer, try to capture immediately
    if is_pursuer:
        for dx, dy, nx, ny in candidates:
            if nx == ox and ny == oy:
                return [dx, dy]

        # Minimax: opponent (evader) maximizes our next distance; we minimize it
        best = None
        for dx, dy, nx, ny in candidates:
            worst_dist = -1
            worst_mob = -1
            for odx, ody in moves:
